import{c as t,Q as e,j as n,m as i}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"AddPlatformInfo","description":"","frontmatter":{},"headers":[{"level":1,"title":"AddPlatformInfo","slug":"addplatforminfo"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/Tiling调测/ContextBuilder/AddPlatformInfo.md","filePath":"api/Utils-API/Tiling调测/ContextBuilder/AddPlatformInfo.md"}'),l={name:"api/Utils-API/Tiling调测/ContextBuilder/AddPlatformInfo.md"};function s(o,a,d,p,r,c){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="addplatforminfo" tabindex="-1">AddPlatformInfo <a class="header-anchor" href="#addplatforminfo" aria-label="Permalink to &quot;AddPlatformInfo&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>设置硬件平台信息便于用户在算子Tiling函数调测中使用。支持以下两种设置方式：</p><ul><li><strong>自动获取当前硬件平台信息</strong>：传入空指针，自动获取当前硬件信息并添加到ContextBuilder类中。</li><li><strong>指定硬件平台信息</strong>：传入具体的AI处理器型号，添加对应硬件信息至ContextBuilder类中。</li></ul><p>若设置失败，会打印报错信息。关于日志配置和查看，请参考。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ContextBuilder &amp;AddPlatformInfo(const char* customSocVersion)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>customSocVersion</td><td>输入</td><td>AI处理器型号。配置方式如下： 针对如下产品：在安装AI处理器的服务器执行npu-smi info命令进行查询，获取Name信息。实际配置值为AscendName，例如Name取值为xxxyy，实际配置值为Ascendxxxyy。 Atlas A2 训练系列产品/Atlas A2 推理系列产品 Atlas 200I/500 A2 推理产品 Atlas 推理系列产品 Atlas 训练系列产品 针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，在安装AI处理器的服务器执行npu-smi info -t board -i id -c chip_id命令进行查询，获取Chip Name和NPU Name信息，实际配置值为Chip Name_NPU Name。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。其中：id：设备id，通过npu-smi info -l命令查出的NPU ID即为设备id。chip_id：芯片id，通过npu-smi info -m命令查出的Chip ID即为芯片id。 针对Ascend 950PR/Ascend 950DT，在安装AI处理器的服务器执行npu-smi info -t board -i id命令进行查询，获取Chip Name和NPU Name信息，实际配置值为Chip Name_NPU Name。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。 其中，id为设备id，通过npu-smi info -l命令查出的NPU ID即为设备id。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>当前ContextBuilder对象。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>AddPlatformInfo调用后需要通过<a href="./BuildTilingContext.html">BuildTilingContext</a>来构建Tiling的上下文，并传递给Tiling函数来使用。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void AddPlatformInfoDemo(......)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    auto holder = context_ascendc::ContextBuilder()</span></span>
<span class="line"><span>	// ... ...</span><span> // 增加算子输入输出接口的调用</span></span>
<span class="line"><span>	.AddPlatformInfo(&quot;Ascendxxxyy&quot;)</span></span>
<span class="line"><span>	.BuildTilingContext();</span></span>
<span class="line"><span>    auto tilingContext = holder-&gt;GetContext&lt;gert::TilingContext&gt;();</span></span>
<span class="line"><span>    // ... ...</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,15)])])}const u=t(l,[["render",s]]);export{m as __pageData,u as default};
